class Solution:
    def construct(self, k: int) -> List[str]:
        if k == 1:
            return ["."]
        bits = bin(k)[3:]
        B = len(bits)
        n = 2 * B + 2
        g = [['#'] * n for _ in range(n)]
        drops = [2 * i + 2 for i, ch in enumerate(bits) if ch == '1']
        top = max(drops) if drops else 1
        for c in range(top + 1):
            g[0][c] = '.'
        for i in range(B + 1):
            g[2 * i + 1][2 * i + 1] = '.'
        for i, ch in enumerate(bits):
            r = c = 2 * i + 1
            g[r][c + 1] = g[r + 1][c] = g[r + 1][c + 1] = g[r + 2][c + 1] = '.'
            if ch == '1':
                for rr in range(r + 1):
                    g[rr][c + 1] = '.'
        return [''.join(row) for row in g]

