class Solution {
public:
    vector<string> construct(int k) {
        if (k == 1) return {"."};
        string bits;
        for (int t = k; t > 1; t >>= 1) bits += char('0' + (t & 1));
        reverse(bits.begin(), bits.end());
        int B = bits.size(), n = 2 * B + 2;
        vector<string> g(n, string(n, '#'));
        int top = 1;
        for (int i = 0; i < B; i++)
            if (bits[i] == '1') top = max(top, 2 * i + 2);
        for (int c = 0; c <= top; c++) g[0][c] = '.';
        for (int i = 0; i <= B; i++) g[2 * i + 1][2 * i + 1] = '.';
        for (int i = 0; i < B; i++) {
            int r = 2 * i + 1, c = 2 * i + 1;
            g[r][c + 1] = g[r + 1][c] = g[r + 1][c + 1] = g[r + 2][c + 1] = '.';
            if (bits[i] == '1')
                for (int rr = 0; rr <= r; rr++) g[rr][c + 1] = '.';
        }
        return g;
    }
};

