class Solution {
    public String[] construct(int k) {
        if (k == 1) return new String[]{"."};
        StringBuilder sb = new StringBuilder();
        for (int t = k; t > 1; t >>= 1) sb.append((char) ('0' + (t & 1)));
        sb.reverse();
        String bits = sb.toString();
        int B = bits.length(), n = 2 * B + 2;
        char[][] g = new char[n][n];
        for (char[] row : g) java.util.Arrays.fill(row, '#');
        int top = 1;
        for (int i = 0; i < B; i++)
            if (bits.charAt(i) == '1') top = Math.max(top, 2 * i + 2);
        for (int c = 0; c <= top; c++) g[0][c] = '.';
        for (int i = 0; i <= B; i++) g[2 * i + 1][2 * i + 1] = '.';
        for (int i = 0; i < B; i++) {
            int r = 2 * i + 1, c = 2 * i + 1;
            g[r][c + 1] = g[r + 1][c] = g[r + 1][c + 1] = g[r + 2][c + 1] = '.';
            if (bits.charAt(i) == '1')
                for (int rr = 0; rr <= r; rr++) g[rr][c + 1] = '.';
        }
        String[] res = new String[n];
        for (int i = 0; i < n; i++) res[i] = new String(g[i]);
        return res;
    }
}

