var construct = function(k) {
    if (k === 1) return ["."];
    let bits = "";
    for (let t = k; t > 1; t >>= 1) bits += (t & 1);
    bits = bits.split("").reverse().join("");
    const B = bits.length, n = 2 * B + 2;
    const g = Array.from({length: n}, () => Array(n).fill('#'));
    let top = 1;
    for (let i = 0; i < B; i++)
        if (bits[i] === '1') top = Math.max(top, 2 * i + 2);
    for (let c = 0; c <= top; c++) g[0][c] = '.';
    for (let i = 0; i <= B; i++) g[2 * i + 1][2 * i + 1] = '.';
    for (let i = 0; i < B; i++) {
        const r = 2 * i + 1, c = 2 * i + 1;
        g[r][c + 1] = g[r + 1][c] = g[r + 1][c + 1] = g[r + 2][c + 1] = '.';
        if (bits[i] === '1')
            for (let rr = 0; rr <= r; rr++) g[rr][c + 1] = '.';
    }
    return g.map(row => row.join(""));
};
